const webhookData = $('Webhook').first().json;
const urls = webhookData.body.urls || [];
const batchContext = $('Split URLs').context;
const currentIndex = batchContext?.currentRunIndex || 0;
const batchSize = webhookData.body.options?.batch_size || 5;

// Get current batch of URLs
const startIdx = currentIndex * batchSize;
const batchUrls = urls.slice(startIdx, startIdx + batchSize);

return batchUrls.map(url => ({
  json: {
    url: url,
    webhookData: webhookData
  }
}));

const items = $input.all();
const webhookData = $('Webhook').first().json;

const results = items.map((item, idx) => {
  const url = item.json.url || `url-${idx}`;
  const statusCode = item.json.statusCode || 0;
  const body = item.json.body || '';

  // Extract title
  let title = '';
  const titleMatch = body.match(/<title[^>]*>([^<]*)<\/title>/i);
  if (titleMatch) title = titleMatch[1].trim();

  // Extract description
  let description = '';
  const descMatch = body.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']*)["'][^>]*>/i);
  if (descMatch) description = descMatch[1];

  const success = statusCode >= 200 && statusCode < 400;

  return {
    url: url,
    success: success,
    status_code: statusCode,
    title: title,
    description: description,
    content_length: body.length,
    error: success ? null : `HTTP ${statusCode}`
  };
});

return [{ json: { batch_results: results } }];

const items = $input.all();
const webhookData = $('Webhook').first().json;
const startTime = Date.now();

// Collect all batch results
const allResults = [];
items.forEach(item => {
  if (item.json.batch_results) {
    allResults.push(...item.json.batch_results);
  }
});

const successful = allResults.filter(r => r.success).length;
const failed = allResults.filter(r => !r.success).length;

return [{
  json: {
    success: true,
    data: {
      results: allResults,
      summary: {
        total: allResults.length,
        successful: successful,
        failed: failed,
        success_rate: allResults.length > 0 ? (successful / allResults.length * 100).toFixed(1) + '%' : '0%'
      }
    },
    meta: {
      provider: 'bulk-processor',
      execution_mode: webhookData.body.execution_mode || 'online',
      batch_size: webhookData.body.options?.batch_size || 5,
      processing_time_ms: Date.now() - startTime
    }
  }
}];

